WITH source AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM `newzl`.`hsj_stock_hq_basic`), eligible AS (SELECT * FROM source WHERE lookback_row<=10), daily AS (SELECT mktcode,tgtcode,bizdate,MAX(volume) AS value FROM eligible GROUP BY mktcode,tgtcode,bizdate), sequenced AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS all_seq FROM daily), hits AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS hit_seq FROM sequenced WHERE value>0), runs AS (SELECT mktcode,tgtcode,all_seq-hit_seq AS grp,COUNT(*) AS n FROM hits GROUP BY mktcode,tgtcode,all_seq-hit_seq), qualified AS (SELECT mktcode,tgtcode FROM runs GROUP BY mktcode,tgtcode HAVING MAX(n)>=3) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
